function clone(v){return JSON.parse(JSON.stringify(v))}
function mergeDeep(base,extra){const out=clone(base);if(!extra||typeof extra!=='object')return out;for(const k of Object.keys(extra)){if(extra[k]&&typeof extra[k]==='object'&&!Array.isArray(extra[k])&&out[k]&&typeof out[k]==='object'&&!Array.isArray(out[k]))out[k]=mergeDeep(out[k],extra[k]);else out[k]=extra[k]}return out}
function loadState(){try{const raw=localStorage.getItem(KEY);let s;if(raw)s=mergeDeep(DEFAULT,JSON.parse(raw));else{const legacy=localStorage.getItem('bold_v2');if(legacy){const x=JSON.parse(legacy);s=mergeDeep(DEFAULT,x);if(x.challengeProgress){for(const [id,p] of Object.entries(x.challengeProgress)){const map=id==='g48'?'g28':id;if(s.challenges[map])s.challenges[map].completed=p}}}else s=clone(DEFAULT)}if(!s.onboarded&&s.name&&s.name!=='دوست BOLD')s.onboarded=true;delete s.story;delete s.theme;delete s.profileDate;s.gratitudes=(s.gratitudes||[]).map(x=>({...x,createdAt:x.createdAt||`${x.date}T12:00:00`}));return s}catch(e){return clone(DEFAULT)}}
function save(){localStorage.setItem(KEY,JSON.stringify(state))}
function now(){return new Date()}
function localISO(d=now()){const x=new Date(d),y=x.getFullYear(),m=String(x.getMonth()+1).padStart(2,'0'),day=String(x.getDate()).padStart(2,'0');return `${y}-${m}-${day}`}
function dayOffset(n){const d=now();d.setDate(d.getDate()-n);return localISO(d)}
function faDate(s){return new Date(s+'T12:00:00').toLocaleDateString('fa-IR-u-ca-persian',{year:'numeric',month:'long',day:'numeric'})}
function faDateShort(s){return new Date(s+'T12:00:00').toLocaleDateString('fa-IR-u-ca-persian',{year:'numeric',month:'2-digit',day:'2-digit'})}
function faTime(s){const d=s instanceof Date?new Date(s):new Date(s||'');return isNaN(d.getTime())?'—':d.toLocaleTimeString('fa-IR',{hour:'2-digit',minute:'2-digit',hour12:false})}
function gregorianToJalaliLabel(iso){return new Date(iso+'T12:00:00').toLocaleDateString('fa-IR-u-ca-persian',{year:'numeric',month:'2-digit',day:'2-digit'})}
function jalaliToGregorian(jy,jm,jd){jy=+jy-979;jm=+jm-1;jd=+jd-1;let jDay=365*jy+Math.floor(jy/33)*8+Math.floor((jy%33+3)/4);for(let i=0;i<jm;i++)jDay+=(i<6?31:30);jDay+=jd;let gDay=jDay+79;let gy=1600+400*Math.floor(gDay/146097);gDay%=146097;if(gDay>=36525){gDay--;gy+=100*Math.floor(gDay/36524);gDay%=36524;if(gDay>=365)gDay++}gy+=4*Math.floor(gDay/1461);gDay%=1461;if(gDay>=366){gy+=Math.floor((gDay-1)/365);gDay=(gDay-1)%365}let gd=gDay+1,leap=((gy%4===0&&gy%100!==0)||gy%400===0),gm=0;const md=[31,leap?29:28,31,30,31,30,31,31,30,31,30,31];while(gm<12&&gd>md[gm]){gd-=md[gm];gm++}return `${gy}-${String(gm+1).padStart(2,'0')}-${String(gd).padStart(2,'0')}`}
function openJalaliDatePicker(){const cur=currentJalali();const selected=document.getElementById('dateInput')?.value;let y=cur.y,m=cur.m,d=cur.d;if(selected){const parts=new Intl.DateTimeFormat('en-US-u-ca-persian',{year:'numeric',month:'numeric',day:'numeric'}).formatToParts(new Date(selected+'T12:00:00'));y=+parts.find(x=>x.type==='year').value;m=+parts.find(x=>x.type==='month').value;d=+parts.find(x=>x.type==='day').value}openModal(`<div class="jalali-picker"><div class="eyebrow">آرشیو نعمت‌ها</div><h3>انتخاب تاریخ شمسی</h3><p class="muted">روزی را که می‌خواهی در آرشیو ببینی انتخاب کن.</p><div class="jalali-selects"><label>سال<select id="jpYear">${Array.from({length:31},(_,i)=>{const yy=y-15+i;return `<option value="${yy}" ${yy===y?'selected':''}>${faNum(yy)}</option>`}).join('')}</select></label><label>ماه<select id="jpMonth">${Array.from({length:12},(_,i)=>{const mm=i+1;return `<option value="${mm}" ${mm===m?'selected':''}>${faNum(mm)}</option>`}).join('')}</select></label><label>روز<select id="jpDay">${Array.from({length:jalaliMonthLength(y,m)},(_,i)=>{const dd=i+1;return `<option value="${dd}" ${dd===d?'selected':''}>${faNum(dd)}</option>`}).join('')}</select></label></div><div class="jalali-picker-actions"><button class="secondary" onclick="clearDate();closeModal()">همه تاریخ‌ها</button><button class="primary" onclick="applyJalaliPicker()">نمایش این روز</button></div></div>`);['jpMonth','jpYear'].forEach(id=>document.getElementById(id)?.addEventListener('change',()=>updateJalaliPickerDays()))}
function updateJalaliPickerDays(){const y=+(document.getElementById('jpYear')?.value||0),m=+(document.getElementById('jpMonth')?.value||1),d=+(document.getElementById('jpDay')?.value||1),sel=document.getElementById('jpDay');if(!sel)return;const max=jalaliMonthLength(y,m);sel.innerHTML=Array.from({length:max},(_,i)=>{const dd=i+1;return `<option value="${dd}" ${dd===Math.min(d,max)?'selected':''}>${faNum(dd)}</option>`}).join('')}
function applyJalaliPicker(){const y=+(document.getElementById('jpYear')?.value||0),m=+(document.getElementById('jpMonth')?.value||0),d=+(document.getElementById('jpDay')?.value||0);if(!y||m<1||m>12||d<1||d>jalaliMonthLength(y,m))return toast('تاریخ شمسی معتبر نیست.');const date=jalaliToGregorian(y,m,d),i=document.getElementById('dateInput'),b=document.getElementById('jalaliDateButton');if(i)i.value=date;if(b)b.textContent=gregorianToJalaliLabel(date);closeModal();renderGratitudeFeed()}
function syncJalaliDateFromNative(){const i=document.getElementById('dateInput'),b=document.getElementById('jalaliDateButton');if(!i||!b)return;b.textContent=i.value?gregorianToJalaliLabel(i.value):'جستجوی تاریخ شمسی';renderGratitudeFeed()}
function syncJalaliDateFromText(){return} 
function faNum(n){return String(n).replace(/\d/g,d=>'۰۱۲۳۴۵۶۷۸۹'[d])}
function esc(s=''){const d=document.createElement('div');d.textContent=s;return d.innerHTML}
function todayItems(){return state.gratitudes.filter(x=>x.date===localISO())}
function streak(){let s=0;for(let i=0;;i++){if(state.gratitudes.some(x=>x.date===dayOffset(i)))s++;else break}return s}
function gratitudeDayNumber(date){const dates=[...new Set(state.gratitudes.map(x=>x.date).concat(date))].sort();return dates.indexOf(date)+1}
function greet(){const h=now().getHours();let g=h<12?'صبح بخیر':h<16?'ظهر بخیر':h<20?'عصر بخیر':'شب بخیر';return `${g}، ${state.name||'دوستت'} 👋`}
function hideAppKeyboard(){try{document.activeElement?.blur()}catch(_){}try{window.AndroidBridge?.hideKeyboard()}catch(_){} }
function toast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('show'),2200)}
function go(id,b){const current=document.querySelector('.page.active'),next=document.getElementById(id);if(!next||current===next)return;document.querySelectorAll('.page').forEach(x=>x.classList.remove('active'));next.classList.add('active');document.querySelectorAll('.bottom-nav button').forEach(x=>x.classList.toggle('active',x.dataset.page===id));window.scrollTo({top:0,behavior:'smooth'});render()}
function addGratitude(){const e=document.getElementById('gratitudeInput'),text=e.value.trim();if(!text){toast('اول یک نعمت بنویس 🌱');try{e.focus({preventScroll:true})}catch(_){}return}if(todayItems().length>=10)return toast('امروز ۱۰ نعمت ثبت کردی. فردا دوباره ادامه بده 🌱');const d=localISO();state.gratitudes.unshift({id:Date.now(),text,date:d,createdAt:new Date().toISOString(),image:pendingGratitudeImage||''});clearPendingGratitudeImage();save();e.value='';updateTodayProgress();renderGratitudeFeed();updateHomeStats();if(todayItems().length<10){try{e.focus({preventScroll:true})}catch(_){}}}
function setMood(v){state.moods[localISO()]=v;save();document.querySelectorAll('#moodRow button').forEach(b=>b.classList.toggle('selected',+b.dataset.mood===v));toast('حال امروزت ثبت شد ✦');renderCharts()}
function saveTodayNote(){const d=localISO(),t=document.getElementById('todayNote')?.value.trim()||'';if(state.todayNotes[d])return;if(!t)return toast('شرح حال امروزت را بنویس.');state.todayNotes[d]=t;save();hideAppKeyboard();renderGratitudeFeed();render()}
function updateTodayProgress(){const n=Math.min(10,todayItems().length);const count=document.getElementById('todayCount'),progress=document.getElementById('todayProgress'),note=document.getElementById('limitNote'),entry=document.getElementById('gratitudeEntryArea'),done=document.getElementById('gratitudeComplete');if(count)count.textContent=faNum(n);if(progress)progress.style.width=(n*10)+'%';if(note)note.textContent=n>=10?'امروز سهم ۱۰ نعمتت کامل شد. فردا دوباره ادامه بده 🌱':`${faNum(n)} از ۱۰ نعمت امروز`;if(entry)entry.classList.toggle('hidden',n>=10);if(done)done.classList.toggle('hidden',n<10);if(n>=10){clearPendingGratitudeImage();hideAppKeyboard()}}
function updateHomeStats(){const total=state.gratitudes.length,days=new Set(state.gratitudes.map(x=>x.date)).size,s=streak();['homeStreak','homeTotal','homeDays','pStreak','pTotal'].forEach(id=>{const el=document.getElementById(id);if(el)el.textContent=faNum(id.includes('Streak')?s:id.includes('Days')?days:total)});const pc=document.getElementById('pChallenges');if(pc)pc.textContent=faNum(challengeData().filter(c=>{const p=challengeProgress(c.id);return p>0&&p<c.total}).length);const cb=document.getElementById('continueChallengeBtn');if(cb){const lc=challengeData().find(c=>c.id===getLastChallengeId());const lp=lc?challengeProgress(lc.id):0;cb.innerHTML=`✦ ${lp?'ادامه':'شروع'} ${lc?esc(lc.title):'چالش'} <span>‹</span>`}}
function setPendingGratitudeImage(data){pendingGratitudeImage=data;const box=document.getElementById('pendingImagePreview');box.classList.remove('hidden');box.innerHTML=`<img src="${data}" alt="عکس امروز">`;const btn=document.getElementById('clearGratitudeImageBtn');if(btn)btn.classList.remove('hidden')}
function loadGratitudeImage(event){const f=event.target.files?.[0];if(!f)return;compressImage(f,1000,.74).then(setPendingGratitudeImage).catch(()=>toast('بارگذاری عکس انجام نشد.'))}
let cameraTarget=null;
function openCamera(target){cameraTarget=target;if(window.AndroidBridge&&window.AndroidBridge.openCamera){window.AndroidBridge.openCamera();return}const i=document.createElement('input');i.type='file';i.accept='image/*';i.setAttribute('capture','environment');i.onchange=ev=>{const f=ev.target.files?.[0];if(f)compressImage(f,1000,.74).then(onNativeCameraImage).catch(()=>toast('بارگذاری عکس انجام نشد.'))};i.click()}
function recompressDataUrl(data,maxSize=1000,quality=.74){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>{const r=Math.min(1,maxSize/Math.max(img.width,img.height)),c=document.createElement('canvas');c.width=Math.round(img.width*r);c.height=Math.round(img.height*r);c.getContext('2d').drawImage(img,0,0,c.width,c.height);resolve(c.toDataURL('image/jpeg',quality))};img.onerror=reject;img.src=data})}
function onNativeCameraImage(data){const t=cameraTarget;cameraTarget=null;if(!data||!t)return;recompressDataUrl(data,1000,.74).then(img=>{if(t==='gratitude'){setPendingGratitudeImage(img);toast('عکس آماده است ✦')}else if(t.indexOf('post:')===0){const date=t.slice(5);state.gratitudes.filter(x=>x.date===date).forEach(x=>x.image=img);save();closeModal();renderGratitudeFeed()}}).catch(()=>toast('بارگذاری عکس انجام نشد.'))}
function clearPendingGratitudeImage(){pendingGratitudeImage='';['gratitudeImageInput','gratitudeCameraInput'].forEach(id=>{const i=document.getElementById(id);if(i)i.value=''});const box=document.getElementById('pendingImagePreview');if(box){box.classList.add('hidden');box.innerHTML=''}const btn=document.getElementById('clearGratitudeImageBtn');if(btn)btn.classList.add('hidden')}
function compressImage(file,maxSize=900,quality=.72){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>{const ratio=Math.min(1,maxSize/Math.max(img.width,img.height)),c=document.createElement('canvas');c.width=Math.round(img.width*ratio);c.height=Math.round(img.height*ratio);c.getContext('2d').drawImage(img,0,0,c.width,c.height);URL.revokeObjectURL(img.src);resolve(c.toDataURL('image/jpeg',quality))};img.onerror=reject;img.src=URL.createObjectURL(file)})}
function groupByDate(items){const map={};for(const x of items)(map[x.date]??=[]).push(x);return Object.entries(map).sort((a,b)=>b[0].localeCompare(a[0]))}
function choosePostPhoto(date){openModal(`<div class="post-photo-picker"><h3>افزودن عکس</h3><p class="muted">عکس را از گالری انتخاب کن یا با دوربین بگیر.</p><div class="photo-source-grid"><button class="secondary" onclick="triggerPostGallery()">🖼️ گالری</button><button class="secondary" onclick="openCamera('post:${date}')">📷 دوربین</button></div><input id="postGalleryInput" type="file" accept="image/*" hidden onchange="loadPostPhoto(event,'${date}')">`)}
function triggerPostGallery(){document.getElementById('postGalleryInput')?.click()}
function loadPostPhoto(e,date){const f=e.target.files?.[0];if(!f)return;const r=new FileReader();r.onload=()=>{state.gratitudes.filter(x=>x.date===date).forEach(x=>x.image=r.result);save();closeModal();renderGratitudeFeed()};r.readAsDataURL(f)}
function handlePostPhoto(date,has){if(has)deletePostPhoto(date);else choosePostPhoto(date)}
function deletePostPhoto(date){state.gratitudes.filter(x=>x.date===date).forEach(x=>x.image='');save();renderGratitudeFeed()}
function toggleLike(date){state.likes[date]=!state.likes[date];save();renderGratitudeFeed()}
let dialogResolve=null;
function closeDialog(val){const d=document.getElementById('appDialog');if(d)d.remove();const r=dialogResolve;dialogResolve=null;if(r)r(val)}
function showDialog(o){return new Promise(res=>{closeDialog(null);dialogResolve=res;const d=document.createElement('div');d.id='appDialog';d.className='dlg-backdrop';d.innerHTML=`<div class="dlg-box" role="dialog" aria-modal="true"><h4>${esc(o.title)}</h4>${o.text?`<p>${esc(o.text)}</p>`:''}${o.input?`<textarea class="dlg-input" rows="3" maxlength="200" placeholder="${esc(o.placeholder||'')}"></textarea>`:''}<div class="dlg-actions"><button type="button" class="dlg-cancel">انصراف</button><button type="button" class="dlg-ok ${o.danger?'danger':''}">${o.okText||'تأیید'}</button></div></div>`;document.body.appendChild(d);d.addEventListener('click',e=>{if(e.target===d)closeDialog(null)});d.querySelector('.dlg-cancel').onclick=()=>closeDialog(null);d.querySelector('.dlg-ok').onclick=()=>closeDialog(o.input?d.querySelector('textarea').value:true);if(o.input)setTimeout(()=>{const x=d.querySelector('textarea');if(x)x.focus()},60)})}
function askConfirm(o){return showDialog(o)}
function askText(o){return showDialog({...o,input:true})}
async function deletePost(date){const ok=await askConfirm({title:`همه نعمت‌های ${faDate(date)} حذف شوند؟`,text:'این کار قابل بازگشت نیست.',okText:'حذف',danger:true});if(!ok)return;state.gratitudes=state.gratitudes.filter(x=>x.date!==date);delete state.todayNotes[date];delete state.likes[date];save();render();toast('پست حذف شد.')}
function toggleCaption(date){const details=document.querySelector(`[data-caption="${date}"]`),btn=document.querySelector(`[data-caption-toggle="${date}"]`);if(!details)return;const open=!details.classList.contains('expanded');details.classList.toggle('expanded',open);if(btn)btn.innerHTML=open?'بستن جزئیات <b>⌃</b>':'مشاهده نعمات و شرح حال <b>⌄</b>';}
function renderGratitudeFeed(){const host=document.getElementById('gratitudeFeed');if(!host)return;const q=(document.getElementById('searchInput')?.value||'').trim().toLowerCase(),date=document.getElementById('dateInput')?.value||'';const filtered=state.gratitudes.filter(x=>(!q||(x.text+' '+(state.todayNotes[x.date]||'')).toLowerCase().includes(q))&&(!date||x.date===date));const count=document.getElementById('gratitudeCount');if(count)count.textContent=faNum(filtered.length)+' مورد';const groups=groupByDate(filtered);if(!groups.length){host.innerHTML='<div class="card empty-gratitude"><svg viewBox="0 0 220 150" aria-hidden="true"><circle cx="110" cy="76" r="42"/><path d="M86 78c10-17 38-17 48 0M94 60h2m28 0h2M75 110c18-12 52-12 70 0"/><path d="M48 116c18-20 20-46 6-65M172 116c-18-20-20-46-6-65"/></svg><b>هنوز نعمتی ثبت نکردی</b><span>با جستجوی تاریخ شمسی یا متن، آرشیوت را پیدا کن ✦</span></div>';return}host.innerHTML=groups.map(([d,arr])=>{const image=arr.find(x=>x.image)?.image||'';const liked=!!state.likes[d];const note=state.todayNotes[d]||'';const lines=arr.map(x=>`<div>${esc(x.text)}</div>`).join('');return `<article class="daily-post card" data-date="${d}"><div class="post-header"><div class="post-user"><div class="post-avatar">${state.profileImage?`<img src="${state.profileImage}" alt="">`:esc((state.name||'ب')[0])}</div><div class="post-headline"><b>${esc(state.name||'دوست بولد')}</b><small>قدردانی روز ${faNum(gratitudeDayNumber(d))}</small></div></div><div class="post-head-actions"><button class="post-photo ${image?'has-photo':''}" onclick="handlePostPhoto('${d}',${!!image})">${image?'حذف عکس':'+ عکس'}</button><button class="post-menu" onclick="deletePost('${d}')" aria-label="حذف">⋯</button></div></div><div class="post-image" onclick="openMediaViewer('${d}')">${image?`<img src="${image}" alt="${faDate(d)}">`:'<div class="post-placeholder">✦</div>'}</div><div class="post-actions"><button class="like-btn ${liked?'liked':''}" onclick="toggleLike('${d}')" aria-label="لایک"><svg viewBox="0 0 24 24"><path d="M20.8 8.9c0 5.1-8.8 10.1-8.8 10.1S3.2 14 3.2 8.9A4.7 4.7 0 0 1 12 6.1a4.7 4.7 0 0 1 8.8 2.8Z"/></svg></button><span class="hint-inline">${faNum(arr.length)} نعمت</span></div><button class="post-caption compact" data-caption-toggle="${d}" type="button" onclick="toggleCaption('${d}')"><span class="post-time">${faTime(arr.reduce((a,x)=>new Date(a).getTime()>new Date(x.createdAt||x.date).getTime()?a:(x.createdAt||x.date),arr[0]?.createdAt||d))}</span><span class="post-caption-hint" data-more="${d}">مشاهده نعمات و شرح حال <b>⌄</b></span></button><div class="post-details" data-caption="${d}"><div class="blessing-lines expanded">${lines}</div>${note?`<div class="post-note"><b>حال آن روز:</b><br>${esc(note)} <button class="edit-note" onclick="event.stopPropagation();editTodayNote('${d}')">ویرایش</button></div>`:'<div class="post-note muted">شرح حالی برای این روز ثبت نشده است.</div>'}<div class="post-date">${faDate(d)}</div></div></article>`}).join('')}
function clearDate(){const i=document.getElementById('dateInput'),t=document.getElementById('jalaliDateText');if(i)i.value='';if(t)t.value='';renderGratitudeFeed()}
function editTodayNote(date){const current=state.todayNotes[date]||'';openModal(`<div><h3>ویرایش شرح حال</h3><textarea id="editNoteInput" maxlength="500" style="width:100%;min-height:130px">${esc(current)}</textarea><button class="primary" style="margin-top:10px" onclick="saveEditedNote('${date}')">ذخیره</button></div>`)}
function saveEditedNote(date){const t=document.getElementById('editNoteInput')?.value.trim()||'';if(!t)return toast('شرح حال نمی‌تواند خالی باشد.');state.todayNotes[date]=t;save();closeModal();renderGratitudeFeed()}
function currentJalali(){const parts=new Intl.DateTimeFormat('en-US-u-ca-persian',{year:'numeric',month:'numeric',day:'numeric'}).formatToParts(new Date());return {y:+parts.find(x=>x.type==='year').value,m:+parts.find(x=>x.type==='month').value,d:+parts.find(x=>x.type==='day').value}}
function jalaliMonthLength(y,m){if(m<=6)return 31;if(m<=11)return 30;const a=new Date(jalaliToGregorian(y,12,1)+'T12:00:00'),b=new Date(jalaliToGregorian(y+1,1,1)+'T12:00:00');return Math.round((b-a)/86400000)}
function jalaliWeekday(gy){return new Date(gy+'T12:00:00').getDay()}
function renderGratitudeTracker(){const host=document.getElementById('gratitudeTracker'),label=document.getElementById('trackerMonth');if(!host)return;const cur=currentJalali(),days=jalaliMonthLength(cur.y,cur.m),first=jalaliToGregorian(cur.y,cur.m,1),offset=(jalaliWeekday(first)+1)%7; if(label)label.textContent=`${faNum(cur.y)} / ${faNum(cur.m)}`;let cells='';for(let i=0;i<offset;i++)cells+='<span class="tracker-empty"></span>';for(let day=1;day<=days;day++){const date=jalaliToGregorian(cur.y,cur.m,day),count=state.gratitudes.filter(x=>x.date===date).length,active=count>0;cells+=`<button class="tracker-day ${active?'done':''}" onclick="filterByDate('${date}')" title="${faDate(date)}">${faNum(day)}${active?`<i>${faNum(count)}</i>`:''}</button>`}host.innerHTML='<div class="tracker-week"><span>ش</span><span>ی</span><span>د</span><span>س</span><span>چ</span><span>پ</span><span>ج</span></div><div class="tracker-grid">'+cells+'</div>'}
function filterByDate(date){go('gratitudes');setTimeout(()=>{const i=document.getElementById('dateInput'),t=document.getElementById('jalaliDateText');if(i)i.value=date;if(t)t.value=gregorianToJalaliLabel(date);renderGratitudeFeed()},80)}
function dayDateForChallenge(id,day){const c=state.challenges[id];if(c.startedAt){const d=new Date(c.startedAt+'T12:00:00');d.setDate(d.getDate()+day-1);return localISO(d)}return localISO()}
function ensureChallengeStart(id){if(!state.challenges[id].startedAt)state.challenges[id].startedAt=localISO()}
const CH_ICONS={g28:'<svg viewBox="0 0 24 24"><path d="M12 3.5l2.2 5.3 5.3 2.2-5.3 2.2L12 18.5l-2.2-5.3L4.5 11l5.3-2.2L12 3.5Z"/></svg>',c90:'<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="8.5"/><circle cx="12" cy="12" r="4.5"/><circle cx="12" cy="12" r=".8"/></svg>',c30:'<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="4"/><path d="M12 3v2.5M12 18.5V21M3 12h2.5M18.5 12H21M5.6 5.6l1.8 1.8M16.6 16.6l1.8 1.8M5.6 18.4l1.8-1.8M16.6 7.4l1.8-1.8"/></svg>',c100:'<svg viewBox="0 0 24 24"><path d="M20 12.5 12 20 4 12.5A5 5 0 0 1 11.2 5L12 5.8 12.8 5A5 5 0 0 1 20 12.5Z"/></svg>'};
const CHALLENGES={g28:{title:'چالش ۲۸ روزه',subtitle:'هر روز یک نگاه تازه به داشته‌هایت',total:28,icon:CH_ICONS.g28},c90:{title:'چالش ۹۰ روزه',subtitle:'ساختن عادت عمیق قدردانی',total:90,icon:CH_ICONS.c90},c30:{title:'چالش ۳۰ روزه',subtitle:'سی روز سؤال برای دیدن خوبی‌ها',total:30,icon:CH_ICONS.c30},c100:{title:'چالش ۱۰۰ روزه',subtitle:'هر روز پنج نعمت را آگاهانه انتخاب کن',total:100,icon:CH_ICONS.c100}};
function challengeData(){return Object.entries(CHALLENGES).map(([id,c])=>({id,...c}))}
function challengeProgress(id){const c=state.challenges[id];return c?Object.keys(c.days||{}).length:0}
function getLastChallengeId(){if(state.lastChallengeId&&CHALLENGES[state.lastChallengeId])return state.lastChallengeId;const ranked=challengeData().map(c=>({id:c.id,ts:Object.values(state.challenges[c.id]?.days||{}).reduce((m,x)=>Math.max(m,x.updatedAt||0),0),p:challengeProgress(c.id)})).filter(x=>x.p>0).sort((a,b)=>b.ts-a.ts);return ranked[0]?.id||null}
function renderChallenges(){const host=document.getElementById('challengeList');if(!host)return;host.innerHTML=challengeData().map(c=>{const p=Math.min(c.total,challengeProgress(c.id)),pct=Math.round(p/c.total*100),done=p>=c.total,started=p>0;const chip=done?'تکمیل شد':started?'در حال انجام':'شروع نشده';return `<button type="button" class="ch-card ${done?'is-done':''}" onclick="openChallenge('${c.id}')"><span class="ch-ic">${c.icon}</span><span class="ch-body"><span class="ch-title"><b>${c.title}</b><i class="ch-chip ${done?'done':started?'active':''}">${chip}</i></span><small>${c.subtitle}</small><span class="ch-bar"><span style="width:${pct}%"></span></span></span><span class="ch-count"><b>${faNum(p)}</b><small>از ${faNum(c.total)}</small></span></button>`}).join('')}
function openChallenges(){renderChallenges();go('toolbox');setTimeout(()=>document.getElementById('challengeSection')?.scrollIntoView({behavior:'smooth',block:'start'}),100)}
function openLastChallenge(){const id=getLastChallengeId();if(id)openChallenge(id);else{openChallenges();toast('هنوز چالشی شروع نشده؛ یکی را انتخاب کن ✦')}}
function openChallenge(id){const c=CHALLENGES[id];if(!c)return;state.lastChallengeId=id;save();const p=challengeProgress(id);const day=Math.min(c.total,Math.max(1,p+1));openModal(`<div class="challenge-detail"><div class="challenge-detail-head"><div><div class="eyebrow">مسیر قدردانی</div><h3>${c.title}</h3><p class="muted">${c.subtitle}</p></div><span class="challenge-detail-icon">${c.icon}</span></div><div class="challenge-progress-bar"><span style="width:${Math.min(100,p/c.total*100)}%"></span></div><div class="challenge-progress-label"><span>${faNum(p)} روز ثبت شده</span><span>${faNum(c.total)} روز</span></div><div class="day-tabs"><button class="active" id="challengeCurrentTab">روز ${faNum(day)}</button><button onclick="openChallengeHistory('${id}')">تاریخچه</button></div><div id="challengeBody">${challengeDayForm(id,day)}</div></div>`)}
function challengeDayForm(id,day){const saved=state.challenges[id]?.days?.[dayDateForChallenge(id,day)]||{};if(id==='c90'){return `<div class="challenge-entry"><div class="prompt-card">امروز پنج نعمتی که واقعاً برایشان قدردان هستی بنویس.</div><div class="c90-fields">${Array.from({length:5},(_,i)=>`<div class="c90-field"><label>نعمت ${faNum(i+1)} <b>✦</b></label><input id="c90_${i}" value="${esc(saved.gratitudes?.[i]||'')}" placeholder="مثلاً یک آدم عزیز، سلامتی، یک لحظه آرام..."></div>`).join('')}</div><div class="c90-best"><label>بهترین اتفاق امروزت</label><textarea id="c90_best" placeholder="یک اتفاق کوچک یا بزرگ که امروز خوشحالت کرد...">${esc(saved.bestEvent||'')}</textarea></div><button class="primary" style="margin-top:10px" onclick="saveChallengeDay('c90',${day})">ثبت روز ${faNum(day)}</button></div>`}if(id==='c30'){return `<div class="challenge-entry"><div class="prompt-card">${esc(CH30[(day-1)%CH30.length])}</div><textarea id="c30_answer" placeholder="جوابت را اینجا بنویس...">${esc(saved.answer||'')}</textarea><button class="primary" style="margin-top:10px" onclick="saveChallengeDay('c30',${day})">ثبت روز ${faNum(day)}</button></div>`}if(id==='c100'){const prompts=dailyBlessings(day);return `<div class="challenge-entry"><div class="prompt-card">پنج موردی را که امروز بیشتر از همه حس می‌کنی انتخاب کن.</div><div class="c100-count" id="c100_count">${faNum((saved.items||[]).filter(t=>prompts.includes(t)).length)} از ۵ انتخاب شده</div><div class="check-list">${prompts.map((x,i)=>`<label class="check-item"><input id="c100_${i}" type="checkbox" onchange="updateC100Count()" ${saved.items?.includes(x)?'checked':''}><span>${esc(x)}</span></label>`).join('')}</div><textarea id="c100_note" placeholder="اگر خواستی یک جمله هم اضافه کن...">${esc(saved.note||'')}</textarea><button class="primary" style="margin-top:10px" onclick="saveChallengeDay('c100',${day})">ثبت روز ${faNum(day)}</button></div>`}return `<div class="challenge-entry"><div class="prompt-card">${esc(CH28[(day-1)%CH28.length])}</div><textarea id="g28_answer" placeholder="امروز چه چیزی دیدی؟">${esc(saved.answer||'')}</textarea><button class="primary" style="margin-top:10px" onclick="saveChallengeDay('g28',${day})">ثبت روز ${faNum(day)}</button></div>`}
function updateC100Count(){const n=document.querySelectorAll('.check-item input:checked').length,el=document.getElementById('c100_count');if(el)el.textContent=faNum(n)+' از ۵ انتخاب شده'}
function openChallengeHistory(id){const c=CHALLENGES[id],days=Object.values(state.challenges[id]?.days||{}).sort((a,b)=>b.day-a.day);const body=days.length?days.map(x=>`<div class="history-row"><b>روز ${faNum(x.day)} · ${faDate(x.date)}</b><p>${esc(x.gratitudes?.join(' · ')||x.answer||x.items?.join(' · ')||x.bestEvent||x.note||'ثبت شد')}</p></div>`).join(''):'<p class="muted">هنوز روزی ثبت نشده است.</p>';document.getElementById('challengeBody').innerHTML=`<div class="challenge-history"><h4>${c.title}</h4>${body}</div><button class="secondary full" style="margin-top:10px" onclick="openChallenge('${id}')">بازگشت به امروز</button>`}
function saveChallengeDay(id,day){ensureChallengeStart(id);const date=dayDateForChallenge(id,day),base={day,date,updatedAt:Date.now()};if(id==='c90'){const vals=Array.from({length:5},(_,i)=>document.getElementById(`c90_${i}`)?.value.trim()||'');if(vals.filter(Boolean).length<5)return toast('برای این روز هر ۵ نعمت را کامل کن.');base.gratitudes=vals;base.bestEvent=document.getElementById('c90_best')?.value.trim()||'';if(!base.bestEvent)return toast('بهترین اتفاق امروزت را هم بنویس.')}else if(id==='c30'){base.answer=document.getElementById('c30_answer')?.value.trim()||'';if(!base.answer)return toast('جوابت را بنویس تا روز ثبت شود.')}else if(id==='c100'){const prompts=dailyBlessings(day);base.items=prompts.filter((_,i)=>document.getElementById(`c100_${i}`)?.checked);if(base.items.length<5)return toast('پنج نعمت امروز را تیک بزن.');base.note=document.getElementById('c100_note')?.value.trim()||''}else{base.answer=document.getElementById('g28_answer')?.value.trim()||'';if(!base.answer)return toast('یک پاسخ کوتاه هم برای امروز بنویس.')}state.challenges[id].days[date]=base;state.lastChallengeId=id;save();closeModal();renderChallenges();updateHomeStats();toast('روز چالش با موفقیت ثبت شد ✦')}
let mediaViewerState={dates:[],index:0,timer:null};
const MEDIA_PLACEHOLDER="data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 400 400%22%3E%3Crect width=%22400%22 height=%22400%22 fill=%22%23221f25%22/%3E%3Ctext x=%22200%22 y=%22220%22 text-anchor=%22middle%22 fill=%22white%22 font-size=%2260%22%3E✦%3C/text%3E%3C/svg%3E";
function openMediaViewer(date){const dates=[...new Set(state.gratitudes.map(x=>x.date))].sort((a,b)=>b.localeCompare(a));if(!dates.includes(date))dates.unshift(date);const viewer=document.getElementById('mediaViewer'),track=document.getElementById('mediaViewerTrack');if(!viewer||!track)return;const start=Math.max(0,dates.indexOf(date));mediaViewerState={dates,index:start,timer:null};track.innerHTML=dates.map(d=>{const arr=state.gratitudes.filter(x=>x.date===d),image=arr.find(x=>x.image)?.image||'';const note=state.todayNotes[d]||'';const lines=arr.map(x=>`<div>• ${esc(x.text)}</div>`).join('');const latest=arr.reduce((a,x)=>new Date(a).getTime()>new Date(x.createdAt||x.date).getTime()?a:(x.createdAt||x.date),arr[0]?.createdAt||d);return `<section class="media-slide"><img src="${image||MEDIA_PLACEHOLDER}" alt="" draggable="false"><div class="media-details" role="button" tabindex="0" aria-expanded="false" onclick="toggleMediaDetails(this)"><div class="media-details-head"><span class="media-time">${faTime(latest)}</span><span class="media-details-hint"><span class="hint-text">مشاهده نعمات و شرح حال</span><b>⌄</b></span></div><div class="media-details-body"><div class="mdb-lines">${lines}</div>${note?`<p><b>حال آن روز:</b><br>${esc(note)}</p>`:'<p>شرح حالی برای این روز ثبت نشده است.</p>'}<small>${faDate(d)}</small></div></div></section>`}).join('');viewer.classList.remove('hidden','closing');document.body.classList.add('viewer-open');track.style.scrollBehavior='auto';track.scrollTop=start*track.clientHeight;requestAnimationFrame(()=>{track.scrollTop=start*track.clientHeight});track.onscroll=()=>{clearTimeout(mediaViewerState.timer);mediaViewerState.timer=setTimeout(()=>{const h=track.clientHeight||1;mediaViewerState.index=Math.round(track.scrollTop/h);track.querySelectorAll('.media-details.expanded').forEach(el=>{if(el.closest('.media-slide')!==track.children[mediaViewerState.index])collapseMediaDetails(el,true)})},90)}}
function collapseMediaDetails(box,instant){const body=box.querySelector('.media-details-body');box.classList.remove('expanded');box.setAttribute('aria-expanded','false');const t=box.querySelector('.hint-text');if(t)t.textContent='مشاهده نعمات و شرح حال';if(body){if(instant)body.style.transition='none';body.style.maxHeight='0px';if(instant)requestAnimationFrame(()=>{body.style.transition=''})}}
function toggleMediaDetails(box){const body=box.querySelector('.media-details-body');if(!body)return;if(box.classList.contains('expanded')){collapseMediaDetails(box,false);return}box.classList.add('expanded');box.setAttribute('aria-expanded','true');const t=box.querySelector('.hint-text');if(t)t.textContent='بستن جزئیات';body.style.maxHeight=Math.min(body.scrollHeight,Math.round(window.innerHeight*.46))+'px'}
function closeMediaViewer(){const v=document.getElementById('mediaViewer');if(!v||v.classList.contains('hidden')||v.classList.contains('closing'))return;const date=mediaViewerState.dates[mediaViewerState.index];v.classList.add('closing');document.body.classList.remove('viewer-open');setTimeout(()=>{v.classList.add('hidden');v.classList.remove('closing');const t=document.getElementById('mediaViewerTrack');if(t){t.onscroll=null;t.innerHTML=''}const post=date&&document.querySelector(`.daily-post[data-date="${date}"]`);if(post)post.scrollIntoView({block:'start'})},230)}
window.handleAndroidBack=function(){if(document.getElementById('appDialog')){closeDialog(null);return true}const v=document.getElementById('mediaViewer');if(v&&!v.classList.contains('hidden')){closeMediaViewer();return true}const m=document.getElementById('modal');if(m&&m.classList.contains('show')){closeModal();return true}return false}
function setRange(v){range=v;document.getElementById('range7').classList.toggle('active',v===7);document.getElementById('range30').classList.toggle('active',v===30);document.getElementById('rangeLabel').textContent=v===7?'۷ روز اخیر':'۳۰ روز اخیر';renderCharts()}
function drawChart(id,data,max=5){const c=document.getElementById(id);if(!c)return;const dpr=window.devicePixelRatio||1,w=Math.max(280,c.clientWidth||c.parentElement?.clientWidth||320),h=180;c.width=Math.round(w*dpr);c.height=Math.round(h*dpr);c.style.width='100%';c.style.height=h+'px';const ctx=c.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);ctx.font='10px BOLDLocal,Tahoma';ctx.direction='rtl';ctx.strokeStyle='#E9E2DB';ctx.lineWidth=1;for(let i=1;i<4;i++){const y=h*i/4;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()}const valid=data.map((v,i)=>({v,i})).filter(x=>x.v>0);if(!valid.length){ctx.fillStyle='#827B78';ctx.textAlign='center';ctx.fillText('هنوز حالتی برای نمایش ثبت نشده است',w/2,h/2);return}ctx.strokeStyle='#9B7AB5';ctx.lineWidth=2.5;ctx.lineJoin='round';ctx.lineCap='round';ctx.beginPath();valid.forEach((p,j)=>{const x=data.length===1?w/2:p.i*w/(data.length-1),y=h-24-(p.v/max)*(h-42);j?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke();valid.forEach(p=>{const x=data.length===1?w/2:p.i*w/(data.length-1),y=h-24-(p.v/max)*(h-42);ctx.fillStyle='#9B7AB5';ctx.beginPath();ctx.arc(x,y,4,0,Math.PI*2);ctx.fill()})}
function renderCharts(){const m=Array.from({length:range},(_,i)=>state.moods[dayOffset(range-1-i)]||0);drawChart('moodChart',m,5)}
function reminderOptions(){const sel=document.getElementById('reminderMessageSelect');if(!sel)return;const items=[...QUOTES.map((text,i)=>({id:'q'+i,text})),...(state.customMessages||[]).map(x=>({id:'c'+x.id,text:x.text}))];sel.innerHTML=items.map(x=>`<option value="${esc(x.id)}">${esc(x.text)}</option>`).join('');const found=items.find(x=>x.text===state.reminder.message);if(found)sel.value=found.id}
function setReminderMode(mode){state.reminder.mode=mode;save();document.querySelectorAll('[data-reminder-mode]').forEach(b=>b.classList.toggle('active',b.dataset.reminderMode===mode))}
function saveReminder(){const v=document.getElementById('reminderTime')?.value;if(!v)return toast('یک زمان انتخاب کن.');const [h,m]=v.split(':').map(Number),sel=document.getElementById('reminderMessageSelect'),selected=sel?.selectedOptions?.[0]?.text||QUOTES[0];state.reminder={...state.reminder,enabled:true,hour:h,minute:m,message:selected,mode:state.reminder.mode||'daily'};save();window.AndroidReminder?.setMotivationReminder(h,m,selected,state.reminder.mode);renderReminder();toast('یادآوری جمله انگیزشی فعال شد ⏰')}
function saveGratitudeReminder(){const v=document.getElementById('gratitudeReminderTime')?.value;if(!v)return toast('یک زمان انتخاب کن.');const [h,m]=v.split(':').map(Number);state.gratitudeReminder={enabled:true,hour:h,minute:m};save();window.AndroidReminder?.setGratitudeReminder(h,m);renderReminder();toast('یادآوری شکرگزاری فعال شد 🌱')}
function renderReminder(){reminderOptions();const r=document.getElementById('reminderStatus'),g=document.getElementById('gratitudeReminderStatus');if(r)r.textContent=state.reminder.enabled?`فعال: هر روز ساعت ${String(state.reminder.hour).padStart(2,'0')}:${String(state.reminder.minute).padStart(2,'0')}`:'هنوز فعال نشده';if(g)g.textContent=state.gratitudeReminder.enabled?`فعال: هر روز ساعت ${String(state.gratitudeReminder.hour).padStart(2,'0')}:${String(state.gratitudeReminder.minute).padStart(2,'0')}`:'هنوز فعال نشده';const rt=document.getElementById('reminderTime'),gt=document.getElementById('gratitudeReminderTime');if(rt)rt.value=`${String(state.reminder.hour).padStart(2,'0')}:${String(state.reminder.minute).padStart(2,'0')}`;if(gt)gt.value=`${String(state.gratitudeReminder.hour).padStart(2,'0')}:${String(state.gratitudeReminder.minute).padStart(2,'0')}`;document.querySelectorAll('[data-reminder-mode]').forEach(b=>b.classList.toggle('active',b.dataset.reminderMode===(state.reminder.mode||'daily')))}
function openReminderFromTool(){go('profile');setTimeout(()=>document.querySelector('.reminder-card')?.scrollIntoView({behavior:'smooth',block:'center'}),120)}
function openCounter(){openModal(`<div class="counter" id="counterArea" onclick="tapCounter(event)"><div class="eyebrow">شکرشمار</div><h3>هر لمس = یک تشکر</h3><div class="counter-number" id="counterNumber">${faNum(counter)}</div><div class="counter-hint">هر جای این قاب را لمس کن.</div><button class="secondary counter-reset" onclick="event.stopPropagation();resetCounter()">ریست</button></div>`)}
let counter=Number(localStorage.getItem('bold_counter')||0);function tapCounter(e){if(e.target.closest('button'))return;counter++;localStorage.setItem('bold_counter',counter);document.getElementById('counterNumber').textContent=faNum(counter);const p=document.createElement('div');p.className='counter-plus';p.textContent='+۱';const r=document.getElementById('counterArea').getBoundingClientRect();p.style.left=(e.clientX-r.left-10)+'px';p.style.top=(e.clientY-r.top-15)+'px';document.getElementById('counterArea').appendChild(p);setTimeout(()=>p.remove(),800)}function resetCounter(){counter=0;localStorage.setItem('bold_counter','0');document.getElementById('counterNumber').textContent='۰'}
function openMessages(){const custom=state.customMessages||[];openModal(`<h3>پیام‌های انگیزشی</h3><div class="message-item"><div class="message-body"><b>پیام تصادفی</b><br><span id="modalQuote">${esc(QUOTES[quoteIndex])}</span></div><button class="small-action" onclick="shuffleQuote(true)">⤨ شافل</button></div>${QUOTES.slice(0,12).map((q,i)=>`<div class="message-item"><div class="message-body">${esc(q)}</div><button class="small-action" onclick="useQuoteAsReminder(${i})">یادآوری</button></div>`).join('')}<div class="message-item"><div class="message-body"><b>جمله‌های من</b><br>${custom.length?'جمله‌های شخصی ذخیره‌شده را می‌توانی حذف کنی.':'هنوز جمله شخصی اضافه نکرده‌ای.'}</div><button class="small-action" onclick="addCustomMessage()">+ اضافه کن</button></div>${custom.map(x=>`<div class="message-item"><div class="message-body">${esc(x.text)}</div><div class="message-actions"><button class="small-action" onclick="useCustomAsReminder(${x.id})">یادآوری</button><button class="small-action" onclick="deleteCustomMessage(${x.id})">حذف</button></div></div>`).join('')}`)}
function shuffleQuote(inModal=false){let n;do{n=Math.floor(Math.random()*QUOTES.length)}while(QUOTES.length>1&&n===quoteIndex);quoteIndex=n;document.getElementById('dailyQuote').textContent=QUOTES[quoteIndex];if(inModal){const q=document.getElementById('modalQuote');if(q)q.textContent=QUOTES[quoteIndex]}}
function useQuoteAsReminder(i){state.reminder.message=QUOTES[i];save();closeModal();go('profile');setTimeout(()=>{reminderOptions();document.getElementById('reminderMessageSelect').value='q'+i},150);toast('این جمله برای یادآوری انتخاب شد ✦')}
function useCustomAsReminder(id){const x=state.customMessages.find(x=>x.id===id);if(!x)return;state.reminder.message=x.text;save();closeModal();go('profile');setTimeout(()=>{reminderOptions();document.getElementById('reminderMessageSelect').value='c'+id},150);toast('جمله شخصی برای یادآوری انتخاب شد ✦')}
async function addCustomMessage(){const t=await askText({title:'جملهٔ انگیزشی خودت را بنویس',okText:'ذخیره',placeholder:'مثلاً: من برای امروز کافی‌ام.'});if(t&&t.trim()){state.customMessages.push({id:Date.now(),text:t.trim()});save();openMessages();toast('جمله شخصی ذخیره شد ✦')}}
async function deleteCustomMessage(id){const ok=await askConfirm({title:'این جمله حذف شود؟',okText:'حذف',danger:true});if(!ok)return;state.customMessages=state.customMessages.filter(x=>x.id!==id);save();openMessages();toast('جمله حذف شد.')}
function showFeedback(){openModal(`<h3>انتقادات و پیشنهادات</h3><p class="muted">برای بهتر شدن بولد، مستقیم برای ما ایمیل بزن.</p><div class="feedback-email"><b>feedback@boldapp.ir</b><p class="muted">روی دکمه بزن تا برنامه ایمیل دستگاه باز شود.</p></div><button class="primary" onclick="emailFeedback()">نوشتن ایمیل</button>`)}
function emailFeedback(){const subject=encodeURIComponent('انتقاد و پیشنهاد برای بولد');const body=encodeURIComponent('سلام تیم بولد،\n\nمی‌خواهم درباره اپ بولد یک پیشنهاد/انتقاد مطرح کنم:\n\n');window.location.href=`mailto:feedback@boldapp.ir?subject=${subject}&body=${body}`;closeModal()}
function openSettings(){openModal(`<div class="settings-sheet"><h3>تنظیمات</h3><p class="muted">اطلاعات روی همین دستگاه ذخیره می‌شوند.</p><div class="set-section"><div class="set-label">پروفایل</div><div class="set-profile"><div class="settings-avatar">${state.profileImage?`<img src="${state.profileImage}" alt="">`:esc((state.name||'ب')[0])}</div><div class="set-profile-fields"><label class="set-field"><span>نام</span><input id="nameInput" value="${esc(state.name||'')}" placeholder="مثلاً نگین" maxlength="40"></label><label class="set-photo-btn">تغییر عکس پروفایل<input id="profileImageInput" type="file" accept="image/*" hidden onchange="saveProfileImage(event)"></label></div></div><button class="primary" onclick="saveName()">ذخیره تغییرات</button></div><div class="set-section"><div class="set-label">اطلاعات برنامه</div><button class="danger-btn" onclick="clearLocal()">پاک‌سازی اطلاعات این دستگاه</button><small class="set-note">همهٔ نعمت‌ها، حال‌ها و چالش‌های ثبت‌شده از این دستگاه حذف می‌شود.</small></div></div>`)}
function saveProfileImage(e){const f=e.target.files?.[0];if(!f)return;const typed=document.getElementById('nameInput')?.value;compressImage(f,700,.75).then(data=>{state.profileImage=data;save();render();openSettings();const n=document.getElementById('nameInput');if(n&&typed!==undefined)n.value=typed;toast('عکس پروفایل ذخیره شد ✦')})}
function saveName(){const n=document.getElementById('nameInput')?.value.trim();if(!n)return toast('نامت را وارد کن.');state.name=n;state.onboarded=true;save();closeModal();render();toast('اطلاعات ذخیره شد ✦')}
async function clearLocal(){const ok=await askConfirm({title:'تمام اطلاعات این دستگاه پاک شود؟',text:'نعمت‌ها، حال‌ها و چالش‌های ثبت‌شده برای همیشه حذف می‌شوند.',okText:'پاک کن',danger:true});if(ok){localStorage.removeItem(KEY);location.reload()}}
function openModal(content){document.getElementById('modalContent').innerHTML=content;document.getElementById('modal').classList.add('show');document.getElementById('modal').setAttribute('aria-hidden','false')}
function closeModal(){try{stopBreathing()}catch(_){}document.getElementById('modal').classList.remove('show');document.getElementById('modal').setAttribute('aria-hidden','true')}
function onboarding(){if(state.onboarded&&state.name)return;openModal(`<div class="onboarding-card"><div class="onboarding-icon">✦</div><div class="eyebrow">شروع شخصی تو</div><h3>خوش اومدی به بولد</h3><p class="muted">اسمت را بنویس تا بولد با خودت صمیمی‌تر شود. عکس پروفایل اختیاری است.</p><label class="onboarding-label">نام</label><input id="onboardName" class="onboarding-input" placeholder="مثلاً نگین"><div class="onboard-photo"><div id="onboardAvatar" class="settings-avatar">ب</div><label class="secondary small">انتخاب عکس<input id="onboardImage" type="file" accept="image/*" hidden onchange="loadOnboardImage(event)"></label></div><button class="primary" style="margin-top:12px" onclick="finishOnboarding()">شروع کن ✦</button></div>`)}
let onboardingImage='';function loadOnboardImage(e){const f=e.target.files?.[0];if(!f)return;compressImage(f,700,.75).then(data=>{onboardingImage=data;document.getElementById('onboardAvatar').innerHTML=`<img src="${data}" alt="">`})}
function finishOnboarding(){const n=document.getElementById('onboardName')?.value.trim();if(!n)return toast('اسمت را بنویس.');state.name=n;state.profileImage=onboardingImage||state.profileImage;state.onboarded=true;save();closeModal();render();toast(`سلام ${n}، خوش اومدی ✦`)}
function render(){document.getElementById('greeting').textContent=greet();document.getElementById('greetingTitle').textContent='امروز چه چیزی را بولد می‌کنی؟';const p=state.name||'دوست بولد';document.getElementById('profileName').textContent=p;const pa=document.getElementById('profileAvatar');pa.innerHTML=state.profileImage?`<img src="${state.profileImage}" alt="">`:esc(p[0]||'ب');document.getElementById('dailyQuote').textContent=QUOTES[quoteIndex];updateHomeStats();updateTodayProgress();const mv=state.moods[localISO()];document.querySelectorAll('#moodRow button').forEach(b=>b.classList.toggle('selected',+b.dataset.mood===mv));const tn=document.getElementById('todayNote'),hasNote=!!state.todayNotes[localISO()];if(tn){tn.value=state.todayNotes[localISO()]||'';tn.disabled=hasNote;tn.placeholder=hasNote?'شرح حال امروز ثبت شده؛ برای ویرایش از پست نعمت‌ها استفاده کن.':'یک جمله درباره حال و هوای امروزت...'}const nb=document.getElementById('todayNoteSaveBtn');if(nb){nb.disabled=hasNote;nb.textContent=hasNote?'امروز ثبت شده':'ثبت حال امروز';}const moodEntry=document.getElementById('moodNoteEntry'),moodDone=document.getElementById('moodComplete');if(moodEntry)moodEntry.classList.toggle('hidden',hasNote);if(moodDone)moodDone.classList.toggle('hidden',!hasNote);renderGratitudeFeed();renderChallenges();renderReminder();renderGratitudeTracker();requestAnimationFrame(()=>renderCharts())}

/* BOLD v7 — guided breathing studio */
const BREATHING_MODES={
  '478':{name:'۴–۷–۸',desc:'آرام‌سازی عمیق',phases:[['دم',4,'in'],['حبس',7,'hold'],['بازدم',8,'out']]},
  'box':{name:'جعبه‌ای',desc:'تمرکز و تعادل',phases:[['دم',4,'in'],['حبس',4,'hold'],['بازدم',4,'out'],['حبس',4,'hold']]},
  'relax':{name:'آرام ۴–۶',desc:'تنفس نرم',phases:[['دم',4,'in'],['بازدم',6,'out']]}
};
const BREATH_MUSIC=[{id:'music1',name:'موسیقی یک',src:'audio/music1.mp3'},
                    {id:'music2',name:'موسیقی دو',src:'audio/music2.mp3'},
                    {id:'music3',name:'موسیقی سه',src:'audio/music3.mp3'}
                   ];
let breathState={mode:'478',running:false,phaseIndex:0,remaining:0,totalPhase:0,startedAt:0,timer:null,audio:null,music:'rain',musicTimer:null};
function openBreathing(){openModal(`<div class="breathing-modal" id="breathingModal"><div class="breathing-head"><div><div class="eyebrow">جعبه ابزار</div><h3>تمرین تنفس</h3><p>با دایره همراه شو؛ فقط ریتم را دنبال کن.</p></div></div><div class="breathing-stage"><div class="breathing-orbit"></div><div class="breathing-circle" id="breathingCircle"><div><div class="breathing-phase" id="breathingPhase">آماده‌ای؟</div><span class="breathing-count" id="breathingCount">—</span></div></div><div class="breathing-tip" id="breathingTip">شروع را بزن و با دایره نفس بکش.</div></div><div class="breathing-progress"><span id="breathingProgress"></span></div><div class="breathing-modes">${Object.entries(BREATHING_MODES).map(([id,m])=>`<button class="breathing-mode ${id==='478'?'active':''}" onclick="selectBreathingMode('${id}')"><b>${m.name}</b><small>${m.desc}</small></button>`).join('')}</div><div class="breathing-music"><div>موسیقی آرامش‌بخش · لوپ</div><div class="music-list">${BREATH_MUSIC.map((m,i)=>`<button class="music-option ${i===0?'active':''}" onclick="selectBreathMusic('${m.id}')">♫ ${m.name}<small>لوپ پیوسته</small></button>`).join('')}</div></div><div class="breathing-controls"><button class="primary" id="breathingStartBtn" onclick="toggleBreathing()">شروع تمرین</button><button class="secondary" onclick="resetBreathing()">از اول</button></div></div>`);resetBreathing();}
function selectBreathingMode(id){if(!BREATHING_MODES[id])return;breathState.mode=id;resetBreathing();document.querySelectorAll('.breathing-mode').forEach((b,i)=>{const key=Object.keys(BREATHING_MODES)[i];b.classList.toggle('active',key===id)});}
function selectBreathMusic(id){breathState.music=id;document.querySelectorAll('.music-option').forEach(b=>b.classList.toggle('active',b.textContent.includes(BREATH_MUSIC.find(x=>x.id===id)?.name||'')));if(breathState.running)startBreathAudio();}
function resetBreathing(){stopBreathing();breathState.phaseIndex=0;breathState.remaining=0;breathState.totalPhase=0;const c=document.getElementById('breathingCircle');if(c)c.style.transform='scale(.72)';const phase=document.getElementById('breathingPhase');if(phase)phase.textContent='آماده‌ای؟';const count=document.getElementById('breathingCount');if(count)count.textContent='—';const tip=document.getElementById('breathingTip');if(tip)tip.textContent='شروع را بزن و با دایره نفس بکش.';const p=document.getElementById('breathingProgress');if(p)p.style.width='0%';const btn=document.getElementById('breathingStartBtn');if(btn)btn.textContent='شروع تمرین';}
function toggleBreathing(){if(breathState.running){stopBreathing();const btn=document.getElementById('breathingStartBtn');if(btn)btn.textContent='ادامه تمرین';return}breathState.running=true;const btn=document.getElementById('breathingStartBtn');if(btn)btn.textContent='مکث';startBreathAudio();if(!breathState.remaining)beginBreathPhase();else scheduleBreathTick();}
function beginBreathPhase(){const mode=BREATHING_MODES[breathState.mode];const phase=mode.phases[breathState.phaseIndex%mode.phases.length];breathState.totalPhase=phase[1];breathState.remaining=phase[1];breathState.startedAt=performance.now();renderBreathPhase();scheduleBreathTick();}
function scheduleBreathTick(){clearTimeout(breathState.timer);breathState.timer=setTimeout(()=>{if(!breathState.running)return;const elapsed=(performance.now()-breathState.startedAt)/1000;const left=Math.max(0,breathState.totalPhase-Math.floor(elapsed));breathState.remaining=left;renderBreathPhase();if(elapsed>=breathState.totalPhase){breathState.phaseIndex++;breathState.remaining=0;beginBreathPhase()}else scheduleBreathTick()},80);}
function renderBreathPhase(){const mode=BREATHING_MODES[breathState.mode],phase=mode.phases[breathState.phaseIndex%mode.phases.length],duration=phase[1],elapsed=Math.min(duration,(performance.now()-breathState.startedAt)/1000);const left=Math.max(1,Math.ceil(duration-elapsed));const phaseEl=document.getElementById('breathingPhase'),count=document.getElementById('breathingCount'),circle=document.getElementById('breathingCircle'),tip=document.getElementById('breathingTip'),progress=document.getElementById('breathingProgress');if(!phaseEl)return;phaseEl.textContent=phase[0];count.textContent=faNum(left);let scale=.72;if(phase[2]==='in')scale=.72+.28*(elapsed/duration);else if(phase[2]==='out')scale=1-.28*(elapsed/duration);else scale=1;circle.style.transform=`scale(${Math.max(.72,Math.min(1,scale))})`;tip.textContent=phase[2]==='in'?'آرام از بینی نفس بکش':phase[2]==='out'?'آهسته و کامل بازدم کن':'نفست را بدون فشار نگه دار';progress.style.width=((elapsed/duration)*100)+'%';}
function stopBreathing(){breathState.running=false;clearTimeout(breathState.timer);stopBreathAudio();}
function startBreathAudio(){try{stopBreathAudio();const music=BREATH_MUSIC.find(x=>x.id===breathState.music)||BREATH_MUSIC[0];if(!music?.src)return;const audio=new Audio(music.src);audio.loop=true;audio.volume=.28;audio.preload='auto';audio.play().catch(()=>{});breathState.audio=audio}catch(_){} }
function stopBreathAudio(){clearTimeout(breathState.musicTimer);breathState.musicTimer=null;if(breathState.audio){try{breathState.audio.pause();breathState.audio.currentTime=0}catch(_){}breathState.audio=null}}

window.addEventListener('resize',()=>{clearTimeout(window.__resize);window.__resize=setTimeout(renderCharts,120)});
setTimeout(()=>document.getElementById('splash')?.classList.add('fade'),2100);
render();setTimeout(onboarding,550);
